using System;using System.IO;using System.Drawing;using System.Drawing.Printing;using System.Reflection;using System.Windows.Forms;using System.Xml;using EanEtikety;
class Revision25Tests {
 static string dir;static void Check(bool v,string m){if(!v)throw new Exception(m);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 [STAThread]static void Main(string[] args){dir=args[0];Directory.CreateDirectory(dir);try{Run();File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS: preferences without content, v2.4 migration, fresh centered startup layout, all languages and aspect ratios, invalid label does not block saving preferences, paper-size checks, clipping checks, copies and pagination, vector print rendering.");}catch(Exception e){File.WriteAllText(Path.Combine(dir,"failed.txt"),e.ToString());Environment.ExitCode=1;}}
 static void Run(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  foreach(string lang in Loc.Codes)foreach(double w in new[]{10d,20,60,85,150,500})foreach(double h in new[]{10d,20,45,90,500}){Loc.Language=lang;var s=StartupLayout.Create(new StartupProfile{Width=w,Height=h,Language=lang});Check(s.Texts.Count==1&&s.Symbols.Count==0&&s.Kind==13&&!s.Gs1Mode&&s.Copies==1,"factory contents");var t=s.Texts[0];Check(t.Center&&Math.Abs(t.X+t.Width/2-w/2)<.001&&Math.Abs(s.BarX+s.BarWidth/2-w/2)<.001,"horizontal centers");Check(!Engine.Outside(s,t.X,t.Y,t.Width,t.Height)&&!Engine.Outside(s,s.BarX,s.BarY,s.BarWidth,Engine.BarcodeHeight(s)),"fitted geometry "+w+"x"+h);Check(t.Y+t.Height<=s.BarY,"no text barcode overlap");using(var scene=VectorArt.Build(s)){} }
  Loc.Language="sk";string path=Path.Combine(dir,"startup.xml");var old=LabelSettings.Default();old.Width=85;old.Height=55;old.Unit="cm";old.DarkMode=false;old.Texts[0].Text="SECRET PRODUCT";old.Ean="123";old.Symbols.Add(new SymbolItem());Engine.Save(Path.Combine(dir,"old-label.xml"),old);var xml=new XmlDocument();xml.Load(Path.Combine(dir,"old-label.xml"));File.WriteAllText(path,"<StartupProfile><Version>1</Version><Language>hu</Language>"+xml.DocumentElement.OuterXml.Replace("LabelSettings","Label")+"</StartupProfile>");var profile=StartupStore.Load(path);Check(profile.Width==85&&profile.Height==55&&profile.Unit=="cm"&&!profile.DarkMode&&profile.Language=="hu"&&profile.Label==null,"migration ignores invalid content");StartupStore.Save(path,profile);Check(!File.ReadAllText(path).Contains("SECRET")&&!File.ReadAllText(path).Contains("<Label>"),"no content serialized");
  using(var f=new MainForm(path)){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();var s=(LabelSettings)Call(f,"Read");Check(s.Ean==LabelSettings.Default().Ean&&s.Texts[0].Text=="Terméknév"&&s.Width==85&&s.Symbols.Count==0,"fresh startup");((TextBox)Field(f,"ean")).Text="invalid";Call(f,"SaveStartup");Check(StartupStore.Load(path).Width==85,"preferences independent of invalid current barcode");Call(f,"Apply",s);using(var bmp=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bmp,new Rectangle(Point.Empty,bmp.Size));bmp.Save(Path.Combine(dir,"app.png"));}f.Close();}
  Loc.Language="sk";var label=StartupLayout.Create(new StartupProfile());label.Copies=5;using(var doc=new LabelPrintDocument(label)){Check(doc.PageCount==5&&doc.Capacity==1,"roll pagination");Check(doc.FitsPaper(new Rectangle(0,0,237,178)),"requested media fits");Check(!doc.FitsPaper(new Rectangle(0,0,100,100)),"small paper rejected");Check(doc.ContentFits(new RectangleF(0,0,237,178)),"full print area");Check(!doc.ContentFits(new RectangleF(150,150,10,10)),"clipping detection");for(int i=0;i<5;i++)using(var b=new Bitmap(720,540)){b.SetResolution(304.8f,304.8f);using(var g=Graphics.FromImage(b)){g.Clear(Color.White);Check(doc.RenderPage(g,i)==1,"one label per page");}if(i==0)b.Save(Path.Combine(dir,"print-label.png"));}}
  label.Sheet=true;label.Copies=23;using(var doc=new LabelPrintDocument(label)){Check(doc.Capacity==15&&doc.PageCount==2,"sheet pagination");using(var b=new Bitmap(840,1188)){b.SetResolution(101.6f,101.6f);using(var g=Graphics.FromImage(b)){g.Clear(Color.White);Check(doc.RenderPage(g,1)==8,"partial last sheet");}b.Save(Path.Combine(dir,"print-sheet.png"));}
   if(PrinterSettings.InstalledPrinters.Count>0){doc.PrinterSettings.PrinterName=PrinterSettings.InstalledPrinters[0];var preview=new PreviewPrintController{UseAntiAlias=true};doc.PrintController=preview;doc.Print();var pages=preview.GetPreviewPageInfo();Check(pages.Length==2,"PrintDocument pipeline pages");foreach(var page in pages)page.Image.Dispose();File.WriteAllText(Path.Combine(dir,"print-pipeline.txt"),"PASS: actual PrintDocument pipeline with PreviewPrintController, no physical job sent. Printer driver: "+doc.PrinterSettings.PrinterName);}
  }
 }
}
